def score(features: Mapping[str, object]) -> float:
    node = 0
    while True:
        feature_index, threshold, left, right, value = NODES[node]
        if left < 0:
            return value
        if _feature_value(FEATURES[feature_index], features) <= threshold:
            node = left
        else:
            node = right


def _feature_value(feature: str, features: Mapping[str, object]) -> float:
    value = features.get(feature, 0.0)
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0
